import { useState } from 'react';
import type { FormEvent } from 'react';
import { useMutation, useQueryClient } from '@tanstack/react-query';
import { useOnce } from '../../query/useOnce';
import { postJson, putJson } from '../../api/http';
import { PersonHead, PersonRow } from '../../slots/defs/personRow';
import { gradeOn, peopleKey, usePeople } from '../people/people';
import type { Person } from '../people/people';
import { useUser } from '../session/session';
import { AMOUNT, CLAIM_AMOUNT, CLAIM_NUMBER, claimsKey, isDeferred, sumAmounts, useClaims } from './claims';
import type { Claim } from './claims';
import { selectClaim, useSelectedClaims } from './selection';
import { claimDue, rateOn, useRates } from '../rates/rates';
import { periodOf, usePeriods } from '../periods/periods';
import { useFloor, useLate } from '../access/access';
import { useSheetToday } from '../sheet/sheet';
import { dueBy, isOverdue } from '../overdue/overdue';

// A clerk's settle above the clerk limit leaves the claim PENDING; a steward approves it or rejects
// it with a reason (typed in the row). A steward re-settles a SETTLED claim at its figure today.
type Action = 'open' | 'settle' | 'void' | 'approve' | 'reject' | 'resettle';
const ACTIONS: { action: Action; label: string }[] = [
  { action: 'open', label: 'Open' },
  { action: 'settle', label: 'Settle' },
  { action: 'void', label: 'Void' },
  { action: 'approve', label: 'Approve' },
  { action: 'reject', label: 'Reject' },
  { action: 'resettle', label: 'Re-settle' },
];

type Fields = { amount: string; date: string; note: string; corrects: string };
const EMPTY: Fields = { amount: '', date: '', note: '', corrects: '' };

function ClaimsHead() {
  return (
    <>
      <th>Claimed</th>
      <th>Claims</th>
    </>
  );
}

// A person's claims: what they have claimed in all, a form that adds a claim (or edits the one
// whose editor is open), and their claims, newest first.
function PersonClaims({ sheetId, person }: { sheetId: string; person: Person }) {
  const queryClient = useQueryClient();
  const all = useClaims(sheetId);
  const claims = (all.data ?? []).filter((c) => c.personId === person.id);
  const [fields, setFields] = useState<Fields>(EMPTY);
  const [editing, setEditing] = useState<string | null>(null);
  const [error, setError] = useState('');
  // The claim whose last status change or edit was refused, and why: its error shows until its
  // next action.
  const [refused, setRefused] = useState<{ id: string; message: string } | null>(null);
  // The reason typed for rejecting each claim, by claim id.
  const [reasons, setReasons] = useState<Record<string, string>>({});
  // The person picked to move each claim to (a steward's move), by claim id.
  const [moveTo, setMoveTo] = useState<Record<string, string>>({});
  // The date typed to defer each claim until, by claim id.
  const [deferUntil, setDeferUntil] = useState<Record<string, string>>({});
  // The new date typed to re-date each claim to, by claim id.
  const [newDate, setNewDate] = useState<Record<string, string>>({});
  // The amount typed to split off each claim, by claim id.
  const [splitAmount, setSplitAmount] = useState<Record<string, string>>({});
  const others = (usePeople(sheetId).data ?? []).filter((p) => p.id !== person.id);
  const [user] = useUser();
  const rates = useRates(sheetId).data ?? [];
  const periods = usePeriods(sheetId).data ?? [];
  const floor = useFloor(sheetId);
  const today = useSheetToday(sheetId);
  const late = useLate(sheetId);
  const selected = useSelectedClaims(sheetId);

  const reset = () => {
    setRefused(null);
    setFields(EMPTY);
    setEditing(null);
    setError('');
  };

  const once = useOnce();
  const save = useMutation({
    mutationFn: ({ id, body }: { id: string | null; body: Fields }) => {
      const sheet = `/api/sheets/${encodeURIComponent(sheetId)}`;
      return id === null
        ? postJson<Claim>(`${sheet}/people/${encodeURIComponent(person.id)}/claims`, body, user)
        : putJson<Claim>(`${sheet}/claims/${encodeURIComponent(id)}`, body, user);
    },
    onSuccess: () => {
      reset();
      void queryClient.invalidateQueries({ queryKey: claimsKey(sheetId) });
    },
    onError: (_e, { id }) => {
      // Only a draft can be edited: an edit of an open (or later) claim is refused on the claim.
      const claim = id === null ? undefined : claims.find((c) => c.id === id);
      if (claim !== undefined && claim.status !== 'DRAFT') {
        setRefused({ id: claim.id, message: 'Only a draft claim can be edited.' });
      } else {
        setError('That claim could not be saved.');
      }
    },
  });

  const move = useMutation({
    mutationFn: ({ id, action }: { id: string; action: Action }) =>
      postJson<Claim>(
        `/api/sheets/${encodeURIComponent(sheetId)}/claims/${encodeURIComponent(id)}/${action}`,
        action === 'reject' ? { reason: (reasons[id] ?? '').trim() } : {},
        user,
      ),
    onSuccess: (_c, { id, action }) => {
      if (action === 'reject') setReasons((r) => ({ ...r, [id]: '' }));
      return queryClient.invalidateQueries({ queryKey: claimsKey(sheetId) });
    },
    onError: (_e, { id }) => setRefused({ id, message: 'That status change is not allowed.' }),
  });

  // A steward moves a DRAFT, OPEN or PENDING claim to another person; it is listed as theirs, newest.
  const reassign = useMutation({
    mutationFn: ({ id, personId }: { id: string; personId: string }) =>
      postJson<Claim>(
        `/api/sheets/${encodeURIComponent(sheetId)}/claims/${encodeURIComponent(id)}/reassign`,
        { personId },
        user,
      ),
    onSuccess: (_c, { id }) => {
      setMoveTo((m) => ({ ...m, [id]: '' }));
      void queryClient.invalidateQueries({ queryKey: peopleKey(sheetId) });
      return queryClient.invalidateQueries({ queryKey: claimsKey(sheetId) });
    },
    onError: (_e, { id }) => setRefused({ id, message: 'That claim cannot be moved.' }),
  });

  // An OPEN claim is deferred until a date after the sheet's today.
  const defer = useMutation({
    mutationFn: ({ id, until }: { id: string; until: string }) =>
      postJson<Claim>(
        `/api/sheets/${encodeURIComponent(sheetId)}/claims/${encodeURIComponent(id)}/defer`,
        { until },
        user,
      ),
    onSuccess: (_c, { id }) => {
      setDeferUntil((d) => ({ ...d, [id]: '' }));
      return queryClient.invalidateQueries({ queryKey: claimsKey(sheetId) });
    },
    onError: (_e, { id }) =>
      setRefused({ id, message: 'Only an OPEN claim can be deferred, to a date after today.' }),
  });

  // A steward re-dates an OPEN or PENDING claim; its due-by and any stated figure are kept.
  const redate = useMutation({
    mutationFn: ({ id, date }: { id: string; date: string }) =>
      postJson<Claim>(
        `/api/sheets/${encodeURIComponent(sheetId)}/claims/${encodeURIComponent(id)}/redate`,
        { date },
        user,
      ),
    onSuccess: (_c, { id }) => {
      setNewDate((d) => ({ ...d, [id]: '' }));
      void queryClient.invalidateQueries({ queryKey: peopleKey(sheetId) });
      return queryClient.invalidateQueries({ queryKey: claimsKey(sheetId) });
    },
    onError: (_e, { id }) =>
      setRefused({
        id,
        message: 'That claim cannot be re-dated: a steward re-dates an open claim, outside a closed period and not after retirement.',
      }),
  });

  const redateClaim = (id: string) => {
    setRefused(null);
    const date = (newDate[id] ?? '').trim();
    if (date === '') {
      setRefused({ id, message: 'Choose the new date for the claim.' });
      return;
    }
    redate.mutate({ id, date });
  };

  // An amount is split off an OPEN claim into a new OPEN claim, listed newest.
  const split = useMutation({
    mutationFn: ({ id, amount }: { id: string; amount: string }) =>
      postJson<Claim>(
        `/api/sheets/${encodeURIComponent(sheetId)}/claims/${encodeURIComponent(id)}/split`,
        { amount },
        user,
      ),
    onSuccess: (_c, { id }) => {
      setSplitAmount((a) => ({ ...a, [id]: '' }));
      return queryClient.invalidateQueries({ queryKey: claimsKey(sheetId) });
    },
    onError: (_e, { id }) =>
      setRefused({ id, message: 'Only an OPEN claim can be split, by an amount less than its own.' }),
  });

  const splitClaim = (id: string) => {
    setRefused(null);
    const amount = (splitAmount[id] ?? '').trim();
    if (!AMOUNT.test(amount)) {
      setRefused({ id, message: 'A split needs an amount with up to two decimals.' });
      return;
    }
    split.mutate({ id, amount });
  };

  // A proof is added to a claim that is not SETTLED or VOID.
  const proof = useMutation({
    mutationFn: (id: string) =>
      postJson<Claim>(
        `/api/sheets/${encodeURIComponent(sheetId)}/claims/${encodeURIComponent(id)}/proof`,
        {},
        user,
      ),
    onSuccess: () => queryClient.invalidateQueries({ queryKey: claimsKey(sheetId) }),
    onError: (_e, id) => setRefused({ id, message: 'A proof cannot be added to that claim.' }),
  });

  const addProof = (id: string) => {
    setRefused(null);
    proof.mutate(id);
  };

  const deferClaim = (id: string) => {
    setRefused(null);
    const until = (deferUntil[id] ?? '').trim();
    if (until === '') {
      setRefused({ id, message: 'Choose the date to defer the claim until.' });
      return;
    }
    defer.mutate({ id, until });
  };

  const moveClaim = (id: string) => {
    setRefused(null);
    const personId = moveTo[id] ?? '';
    if (personId === '') {
      setRefused({ id, message: 'Pick the person to move the claim to.' });
      return;
    }
    reassign.mutate({ id, personId });
  };

  const act = (id: string, action: Action) => {
    setRefused(null);
    if (action === 'reject' && (reasons[id] ?? '').trim() === '') {
      setRefused({ id, message: 'A rejection needs a reason.' });
      return;
    }
    move.mutate({ id, action });
  };

  const submit = (e: FormEvent) => {
    e.preventDefault();
    setError('');
    setRefused(null);
    const amount = fields.amount.trim();
    if (amount === '') {
      setError('An amount is required.');
      return;
    }
    if (!CLAIM_AMOUNT.test(amount)) {
      setError('An amount is a number with up to two decimals.');
      return;
    }
    const corrects = fields.corrects.trim();
    if (amount.startsWith('-') && !CLAIM_NUMBER.test(corrects)) {
      setError('A negative amount is a correction: name the number of the settled claim it corrects.');
      return;
    }
    once((done) => save.mutate({ id: editing, body: { ...fields, amount, corrects } }, { onSettled: done }));
  };

  const change = (next: Partial<Fields>) => {
    setFields((f) => ({ ...f, ...next }));
    setError('');
    setRefused((r) => (r !== null && r.id === editing ? null : r));
  };

  const open = (c: Claim) => {
    setRefused(null);
    setEditing(c.id);
    setFields({ amount: c.amount, date: c.date, note: c.note, corrects: c.corrects });
    setError('');
  };

  return (
    <>
      <td data-testid="person-claimed">{sumAmounts(claims, () => person.holds, today)}</td>
      <td>
        <form onSubmit={submit} data-testid="claim-form">
          <input
            data-testid="claim-form-amount"
            placeholder="Amount"
            inputMode="decimal"
            value={fields.amount}
            onChange={(e) => change({ amount: e.target.value })}
          />{' '}
          <input
            type="date"
            data-testid="claim-form-date"
            value={fields.date}
            onChange={(e) => change({ date: e.target.value })}
          />{' '}
          <input
            data-testid="claim-form-note"
            placeholder="Note"
            value={fields.note}
            onChange={(e) => change({ note: e.target.value })}
          />{' '}
          <input
            data-testid="claim-form-corrects"
            placeholder="Corrects no."
            inputMode="numeric"
            value={fields.corrects}
            onChange={(e) => change({ corrects: e.target.value })}
          />{' '}
          <button type="submit" data-testid="claim-form-submit" disabled={save.isPending}>
            {editing === null ? 'Add claim' : 'Save claim'}
          </button>
          {error && (
            <p role="alert" data-testid="claim-form-error">
              {error}
            </p>
          )}
        </form>
        {all.isError && (
          <p role="alert" data-testid="claims-error">
            The claims could not be read.
          </p>
        )}
        <ul data-testid="claim-list">
          {claims.map((c) => (
            <li key={c.id} data-testid={`claim-row-${c.id}`}>
              <input
                type="checkbox"
                data-testid="claim-select"
                aria-label="Select claim"
                checked={selected.has(c.id)}
                onChange={(e) => selectClaim(sheetId, c.id, e.target.checked)}
              />{' '}
              <span data-testid="claim-number">{c.number}</span>{' '}
              <span data-testid="claim-amount">{c.amount}</span>{' '}
              <span data-testid="claim-date">{c.date}</span>{' '}
              <span data-testid="claim-note">{c.note}</span>{' '}
              <span data-testid="claim-due">{claimDue(c, rateOn(rates, gradeOn(person.grades, c.date), c.date), floor, late)}</span>{' '}
              <span data-testid="claim-status">{c.status}</span>{' '}
              <span data-testid="claim-corrects">{c.corrects}</span>{' '}
              <span data-testid="claim-opened-by">{c.openedBy}</span>{' '}
              <span data-testid="claim-stated">{c.stated ? 'yes' : 'no'}</span>{' '}
              <span data-testid="claim-period">{periodOf(periods, c.date)?.name ?? ''}</span>{' '}
              <span data-testid="claim-due-by">{dueBy(c)}</span>{' '}
              <span data-testid="claim-overdue">{isOverdue(c, today) ? 'yes' : 'no'}</span>{' '}
              <span data-testid="claim-deferred">{isDeferred(c, today) ? 'yes' : 'no'}</span>{' '}
              <span data-testid="claim-deferred-until">{c.deferredUntil}</span>{' '}
              <span data-testid="claim-proofs">{c.proofs}</span>{' '}
              <span data-testid="claim-split-from">{c.splitFrom}</span>{' '}
              <button type="button" data-testid="claim-proof" onClick={() => addProof(c.id)}>
                Add proof
              </button>{' '}
              <input
                data-testid="claim-reject-reason"
                placeholder="Reject reason"
                value={reasons[c.id] ?? ''}
                onChange={(e) => {
                  setReasons((r) => ({ ...r, [c.id]: e.target.value }));
                  setRefused((r) => (r !== null && r.id === c.id ? null : r));
                }}
              />{' '}
              {ACTIONS.map(({ action, label }) => (
                <button
                  key={action}
                  type="button"
                  data-testid={`claim-${action}`}
                  onClick={() => act(c.id, action)}
                >
                  {label}
                </button>
              ))}{' '}
              <input
                type="date"
                data-testid="claim-defer-date"
                aria-label="Defer until"
                value={deferUntil[c.id] ?? ''}
                onChange={(e) => {
                  setDeferUntil((d) => ({ ...d, [c.id]: e.target.value }));
                  setRefused((r) => (r !== null && r.id === c.id ? null : r));
                }}
              />{' '}
              <button type="button" data-testid="claim-defer" onClick={() => deferClaim(c.id)}>
                Defer
              </button>{' '}
              <input
                type="date"
                data-testid="claim-date-new"
                aria-label="New date"
                value={newDate[c.id] ?? ''}
                onChange={(e) => {
                  setNewDate((d) => ({ ...d, [c.id]: e.target.value }));
                  setRefused((r) => (r !== null && r.id === c.id ? null : r));
                }}
              />{' '}
              <button type="button" data-testid="claim-redate" onClick={() => redateClaim(c.id)}>
                Re-date
              </button>{' '}
              <input
                data-testid="claim-split-amount"
                placeholder="Split amount"
                inputMode="decimal"
                value={splitAmount[c.id] ?? ''}
                onChange={(e) => {
                  setSplitAmount((a) => ({ ...a, [c.id]: e.target.value }));
                  setRefused((r) => (r !== null && r.id === c.id ? null : r));
                }}
              />{' '}
              <button type="button" data-testid="claim-split" onClick={() => splitClaim(c.id)}>
                Split
              </button>{' '}
              <select
                data-testid="claim-reassign-to"
                aria-label="Move to"
                value={moveTo[c.id] ?? ''}
                onChange={(e) => {
                  setMoveTo((m) => ({ ...m, [c.id]: e.target.value }));
                  setRefused((r) => (r !== null && r.id === c.id ? null : r));
                }}
              >
                <option value="">Move to…</option>
                {others.map((p) => (
                  <option key={p.id} value={p.id}>
                    {p.name}
                  </option>
                ))}
              </select>{' '}
              <button type="button" data-testid="claim-reassign" onClick={() => moveClaim(c.id)}>
                Move
              </button>{' '}
              {editing === c.id ? (
                <button type="button" data-testid="claim-cancel" onClick={reset}>
                  Cancel
                </button>
              ) : (
                <button type="button" data-testid="claim-edit" onClick={() => open(c)}>
                  Edit
                </button>
              )}
              <ol data-testid="claim-log">
                {c.log.map((line, i) => (
                  <li key={i} data-testid="claim-log-line">
                    {line}
                  </li>
                ))}
              </ol>
              {refused?.id === c.id && (
                <p role="alert" data-testid="claim-error">
                  {refused.message}
                </p>
              )}
            </li>
          ))}
        </ul>
      </td>
    </>
  );
}

export const contributions = [
  PersonHead.fill({ order: 10, Component: ClaimsHead }),
  PersonRow.fill({ order: 10, Component: PersonClaims }),
];
import { useQuery } from '@tanstack/react-query';
import { getJson } from '../../api/http';
import { heldOn } from '../people/people';
import type { Hold } from '../people/people';

/**
 * A claim's status: DRAFT when made, then OPEN, then SETTLED; a clerk's settle above the clerk
 * limit makes it PENDING until a steward approves it (SETTLED) or rejects it (OPEN again). A DRAFT,
 * OPEN or PENDING claim may be VOID; a SETTLED one too, by a steward within 7 days of its settlement.
 */
export type ClaimStatus = 'DRAFT' | 'OPEN' | 'PENDING' | 'SETTLED' | 'VOID';

/**
 * A claim: its amount with two decimals, its date (yyyy-MM-dd), its note, its status and its
 * number on the sheet (given when it is opened; '' for a draft or a voided claim), and its due as
 * fixed when it was settled ('' while its due is live: unsettled, or settled with no rate), and
 * who opened it ('' until it is opened); whether its person's last statement bound it, and the
 * figure it was bound to ('' when not stated; n/a when it had none); and, for a correction (a
 * negative amount), the number of the settled claim it corrects ('' for any other claim); and the
 * date (yyyy-MM-dd) its figures round by (a correction's is the date of the claim it corrects).
 */
export type Claim = {
  id: string;
  personId: string;
  amount: string;
  date: string;
  note: string;
  status: ClaimStatus;
  number: string;
  due: string;
  openedBy: string;
  stated: boolean;
  statedDue: string;
  corrects: string;
  roundDate: string;
  /** Its due-by (yyyy-MM-dd), fixed when it was made: its date plus its person's own terms, else its grade's terms then. */
  dueBy: string;
  /**
   * Its status log, oldest first: one line per status it has had, as
   * `<STATUS> by <user> on <date> due=<due>` (the sheet's today and its due at that moment).
   */
  log: string[];
  /** The date (yyyy-MM-dd) it is deferred until; '' when it was never deferred. */
  deferredUntil: string;
  /** How many proofs it has had added. */
  proofs: number;
  /** The number of the claim it was split off; '' when it was not split off one. */
  splitFrom: string;
};

/** Whether a claim is a correction: it has no floor and no late charge. */
export const isCorrection = (c: Claim) => c.corrects !== '';

/** Whether a claim is open: OPEN, or PENDING a steward's approval. */
export const isOpen = (c: Claim) => c.status === 'OPEN' || c.status === 'PENDING';

/**
 * Whether a claim's stated figure is in force: its person's last statement bound it and it is not
 * PENDING (a PENDING claim shows its live figure).
 */
export const isBound = (c: Claim) => c.stated && c.status !== 'PENDING';

/**
 * Whether a claim is deferred on the sheet's `today`: OPEN and deferred until a date after today.
 * From that date on it is an OPEN claim like any other.
 */
export const isDeferred = (c: Claim, today: string) =>
  c.status === 'OPEN' && c.deferredUntil !== '' && today !== '' && today < c.deferredUntil;

/**
 * Whether a claim counts toward claimed, due-total and every total: only OPEN, PENDING and SETTLED
 * do, and an OPEN or PENDING one not when it is dated within one of its person's `holds`, unless a
 * statement binds it; never one deferred on `today`.
 */
export const counts = (c: Claim, holds: Hold[], today: string) =>
  !isDeferred(c, today) && (c.status === 'SETTLED' || (isOpen(c) && (isBound(c) || !heldOn(holds, c.date))));

/**
 * A claim's status at the end of `day` (yyyy-MM-dd), as its log records it: the status of its last
 * line dated on or before it; null when it had none then (it was added after).
 */
export function statusOn(c: Claim, day: string): ClaimStatus | null {
  let status: ClaimStatus | null = null;
  for (const line of c.log) {
    const m = /^(\w+) by .* on (\d{4}-\d{2}-\d{2}) due=\S*$/.exec(line);
    if (m && m[2] <= day) status = m[1] as ClaimStatus;
  }
  return status;
}

/**
 * Whether a claim counted at the end of `day`: as `counts`, with the status its log records then
 * (never when it was added after), its statement binding and deferral as they are on `today`.
 */
export const countedOn = (c: Claim, day: string, holds: Hold[], today: string) => {
  const status = statusOn(c, day);
  if (status === null || isDeferred(c, today)) return false;
  return status === 'SETTLED' || ((status === 'OPEN' || status === 'PENDING') && (isBound(c) || !heldOn(holds, c.date)));
};

export const claimsKey = (sheetId: string) => ['sheet', sheetId, 'claims'] as const;

export const claimsQuery = (sheetId: string) => ({
  queryKey: claimsKey(sheetId),
  queryFn: async () =>
    (await getJson<{ claims: Claim[] }>(`/api/sheets/${encodeURIComponent(sheetId)}/claims`)).claims,
});

/** The sheet's claims, newest first. */
export function useClaims(sheetId: string) {
  return useQuery(claimsQuery(sheetId));
}

/** An amount as a claim takes it: 0.00 or more, with up to two decimals. */
export const AMOUNT = /^\d+(\.\d{1,2})?$/;

/** An amount as the claim form takes it: up to two decimals, negative for a correction. */
export const CLAIM_AMOUNT = /^-?\d+(\.\d{1,2})?$/;

/**
 * A claim number, as a correction names the claim it corrects: a sheet-wide number, or a number
 * within a period (<period name>-<n>, X-<n> for a claim in no period).
 */
export const CLAIM_NUMBER = /^(\d+|.+-\d+)$/;

/**
 * The amounts of the claims that count (OPEN, PENDING and SETTLED, but not unbound open ones dated within
 * a hold of their person: `holds` tells by person id, nor ones deferred on `today`) added up, in whole cents so no rounding creeps in, shown with two
 * decimals.
 */
export function sumAmounts(claims: Claim[], holds: (personId: string) => Hold[], today: string): string {
  const cents = claims.filter((c) => counts(c, holds(c.personId), today)).reduce((n, c) => n + Math.round(Number(c.amount) * 100), 0);
  return (cents / 100).toFixed(2);
}

