# Edit a claim's amount, date and note. Validate first so a bad amount or date is a 400, not a 404.
# A viewer may change nothing: refused before anything is read or written.
viewer:
  class: net.officefloor.hq.app.role.CheckCanChange
  next: validate
validate:
  class: net.officefloor.hq.app.claim.ValidateClaim
  next: loadSheet
loadSheet:
  class: net.officefloor.hq.app.sheet.LoadSheet
  govern: [ transaction ]
  next: before
# The sheet's figures before the change, so the rollup lines tell which moved.
before:
  class: net.officefloor.hq.app.rollup.TakeRollup
  govern: [ transaction ]
  next: load
load:
  class: net.officefloor.hq.app.claim.LoadClaim
  govern: [ transaction ]
  next: closed
# A claim dated inside a closed period is a 409 and writes nothing.
closed:
  class: net.officefloor.hq.app.period.CheckClaimPeriod
  govern: [ transaction ]
  next: apply
apply:
  class: net.officefloor.hq.app.claim.ApplyClaim
  govern: [ transaction ]
  next: correction
# A correction (a negative amount) must name a settled claim of the same person: else a 400.
correction:
  class: net.officefloor.hq.app.claim.CheckCorrection
  govern: [ transaction ]
  next: closedTo
# Nor may an edit move it into one.
closedTo:
  class: net.officefloor.hq.app.period.CheckClaimPeriod
  govern: [ transaction ]
  next: retired
# Nor may an edit date it after its person's retirement date.
retired:
  class: net.officefloor.hq.app.person.CheckClaimRetired
  govern: [ transaction ]
  next: save
save:
  class: net.officefloor.hq.app.claim.SaveClaim
  govern: [ transaction ]
  next: audit
# Last before the response: every rule has passed and the change is saved.
audit:
  class: net.officefloor.hq.app.claim.AuditClaimEdited
  govern: [ transaction ]
  next: rollup
# After the change's own lines: the figures it moved.
rollup:
  class: net.officefloor.hq.app.rollup.AuditRollup
  govern: [ transaction ]
  next: respond
respond:
  class: net.officefloor.hq.app.claim.RespondWithClaim
  govern: [ transaction ]
# Add a proof to a claim. A SETTLED or VOID claim is a 409 and writes nothing.
# A viewer may change nothing: refused before anything is read or written.
viewer:
  class: net.officefloor.hq.app.role.CheckCanChange
  next: loadSheet
loadSheet:
  class: net.officefloor.hq.app.sheet.LoadSheet
  govern: [ transaction ]
  next: load
load:
  class: net.officefloor.hq.app.claim.LoadClaim
  govern: [ transaction ]
  next: closed
# A claim dated inside a closed period is a 409 and writes nothing.
closed:
  class: net.officefloor.hq.app.period.CheckClaimPeriod
  govern: [ transaction ]
  next: apply
apply:
  class: net.officefloor.hq.app.claim.AddProof
  govern: [ transaction ]
  next: save
save:
  class: net.officefloor.hq.app.claim.SaveClaim
  govern: [ transaction ]
  next: audit
# Last before the response: every rule has passed and the change is saved.
audit:
  class: net.officefloor.hq.app.claim.AuditClaimProofAdded
  govern: [ transaction ]
  next: respond
respond:
  class: net.officefloor.hq.app.claim.RespondWithClaim
  govern: [ transaction ]
package net.officefloor.hq.app.claim;

import net.officefloor.hq.app.sheet.Sheet;
import net.officefloor.plugin.variable.Val;

public class ApplyClaim {
    public void apply(@Val ClaimInput input, @Val Sheet sheet, @Val Claim claim)
            throws InvalidClaimStatusException {
        claim.checkEditable();
        claim.setAmount(input.amount());
        claim.setDate(input.date() == null ? sheet.today() : input.date());
        claim.setNote(input.note());
        claim.setCorrects(input.corrects());
    }
}
package net.officefloor.hq.app.claim;

import net.officefloor.hq.app.sheet.Sheet;
import net.officefloor.plugin.variable.Out;
import net.officefloor.plugin.variable.Val;
import org.springframework.web.bind.annotation.PathVariable;

public class LoadClaim {
    public void load(@PathVariable("claimId") String claimId, @Val Sheet sheet,
            ClaimRepository repository, Out<Claim> claimOut) throws ClaimNotFoundException {
        Claim claim = null;
        try {
            claim = repository.find(sheet.id(), Long.parseLong(claimId));
        } catch (NumberFormatException e) {
            // not an id: not found
        }
        if (claim == null) throw new ClaimNotFoundException(claimId);
        claimOut.set(claim);
    }
}
package net.officefloor.hq.app.claim;

import java.math.BigDecimal;
import java.time.LocalDate;

/** A person's claim, as the store holds it. {@code id} is null until first saved. */
public class Claim {
    private Long id;
    private final String sheetId;
    private long personId;
    private BigDecimal amount;
    private LocalDate date;
    private String note;
    private ClaimStatus status;
    private String number;
    private BigDecimal settledDue;
    private String openedBy;
    private boolean stated;
    private BigDecimal statedDue;
    private String corrects;
    private LocalDate correctedDate;
    private boolean relisted;
    private LocalDate dueBy;
    private LocalDate deferredUntil;
    private int proofs;
    private String splitFrom;

    public Claim(Long id, String sheetId, long personId, BigDecimal amount, LocalDate date, String note,
            ClaimStatus status, String number, BigDecimal settledDue,
            String openedBy) {
        this.id = id;
        this.sheetId = sheetId;
        this.personId = personId;
        this.amount = amount;
        this.date = date;
        this.note = note;
        this.status = status;
        this.number = number;
        this.settledDue = settledDue;
        this.openedBy = openedBy;
    }

    public Long getId() { return id; }
    public void setId(Long id) { this.id = id; }
    public String getSheetId() { return sheetId; }
    public long getPersonId() { return personId; }
    /**
     * Move it to another person: it keeps its number and date, but loses any figure a statement
     * bound it to (it is live again until its new person's next statement). A SETTLED or VOID claim
     * cannot move.
     */
    public void reassign(long toPersonId) throws InvalidClaimStatusException {
        if (status == ClaimStatus.SETTLED || status == ClaimStatus.VOID) {
            throw new InvalidClaimStatusException("A " + status + " claim cannot be moved to another person");
        }
        personId = toPersonId;
        bind(false, null);
        relisted = true;
    }
    /** Whether it was moved since read, so it is listed again as its new person's newest. */
    public boolean isRelisted() { return relisted; }
    public BigDecimal getAmount() { return amount; }
    public void setAmount(BigDecimal amount) { this.amount = amount; }
    public LocalDate getDate() { return date; }
    public void setDate(LocalDate date) { this.date = date; }
    /** Its due-by, fixed when it was made: its date plus its person's own terms, else its grade's terms then. Kept when its date changes. */
    public LocalDate getDueBy() { return dueBy; }
    public void setDueBy(LocalDate dueBy) { this.dueBy = dueBy; }
    /** The date it is deferred until; null when it was never deferred. */
    public LocalDate getDeferredUntil() { return deferredUntil; }
    public void setDeferredUntil(LocalDate deferredUntil) { this.deferredUntil = deferredUntil; }
    /**
     * Whether it is deferred on {@code today}: OPEN, and deferred until a date after today. From
     * that date on it is an OPEN claim like any other.
     */
    public boolean isDeferredOn(LocalDate today) {
        return status == ClaimStatus.OPEN && deferredUntil != null && today != null && today.isBefore(deferredUntil);
    }
    /**
     * Defer it until a date after {@code today}: only an OPEN claim may be deferred.
     */
    public void defer(LocalDate until, LocalDate today) throws InvalidClaimStatusException, InvalidClaimException {
        if (status != ClaimStatus.OPEN) {
            throw new InvalidClaimStatusException("A " + status + " claim cannot be deferred");
        }
        if (!until.isAfter(today)) throw new InvalidClaimException("A claim is deferred to a date after today");
        deferredUntil = until;
    }
    /** How many proofs it has had added. */
    public int getProofs() { return proofs; }
    public void setProofs(int proofs) { this.proofs = proofs; }
    /** Add a proof: not to a SETTLED or VOID claim. */
    public void addProof() throws InvalidClaimStatusException {
        if (status == ClaimStatus.SETTLED || status == ClaimStatus.VOID) {
            throw new InvalidClaimStatusException("A " + status + " claim cannot have a proof added");
        }
        proofs++;
    }
    /** The number of the claim it was split off; null when it was not split off one. */
    public String getSplitFrom() { return splitFrom; }
    public void setSplitFrom(String splitFrom) { this.splitFrom = splitFrom; }
    /**
     * Split {@code part} (more than 0.00, less than its amount) off an OPEN claim that is not
     * deferred on {@code today}: it keeps the rest and loses any figure a statement bound it to.
     * The new claim is made by the caller.
     */
    public void split(BigDecimal part, LocalDate today) throws InvalidClaimStatusException, InvalidClaimException {
        if (status != ClaimStatus.OPEN) {
            throw new InvalidClaimStatusException("A " + status + " claim cannot be split");
        }
        if (isDeferredOn(today)) throw new InvalidClaimStatusException("A deferred claim cannot be split");
        if (part.signum() <= 0 || part.compareTo(amount) >= 0) {
            throw new InvalidClaimException("A split is more than 0.00 and less than the claim's amount");
        }
        amount = amount.subtract(part);
        bind(false, null);
    }
    public String getNote() { return note; }
    public void setNote(String note) { this.note = note; }
    public ClaimStatus getStatus() { return status; }
    /** The number of the settled claim this correction corrects; null when it is no correction. */
    public String getCorrects() { return corrects; }
    public void setCorrects(String corrects) { this.corrects = corrects; }
    /** A correction (a negative amount) has no floor and no late charge. */
    public boolean isCorrection() { return corrects != null; }
    /** The date of the claim this correction corrects; null when it is no correction or not yet read. */
    public LocalDate getCorrectedDate() { return correctedDate; }
    public void setCorrectedDate(LocalDate correctedDate) { this.correctedDate = correctedDate; }
    /** The date its figures round by: a correction's is the date of the claim it corrects. */
    public LocalDate getRoundDate() {
        return isCorrection() && correctedDate != null ? correctedDate : date;
    }
    /** The claim's number on its sheet, given when it is opened; null for a draft. A voided claim
     *  keeps the number it had; a number is never reused. */
    public String getNumber() { return number; }
    public void setNumber(String number) { this.number = number; }
    /** The due fixed when it was settled; null while its due is live. */
    public BigDecimal getSettledDue() { return settledDue; }
    public void setSettledDue(BigDecimal settledDue) { this.settledDue = settledDue; }
    /** The user who opened it; null until it is opened. */
    public String getOpenedBy() { return openedBy; }
    public void setOpenedBy(String openedBy) { this.openedBy = openedBy; }
    /** Whether its person's last statement bound it to a figure. */
    public boolean isStated() { return stated; }
    /** The figure its person's last statement bound it to; null for n/a, or when it is not stated. */
    public BigDecimal getStatedDue() { return statedDue; }
    /**
     * The figure a statement binds it to now: its stated figure (null for n/a), but null when it
     * is not stated or is PENDING (a PENDING claim shows its live figure; a rejection binds it again).
     */
    public BigDecimal boundDue() {
        return isBound() ? statedDue : null;
    }
    /** Whether its stated figure is in force: it is stated and not PENDING. */
    public boolean isBound() {
        return stated && status != ClaimStatus.PENDING;
    }
    /** Bind it to a figure (null: n/a), or leave it unbound (live) when {@code stated} is false. */
    public void bind(boolean stated, BigDecimal statedDue) {
        this.stated = stated;
        this.statedDue = stated ? statedDue : null;
    }
    /**
     * Whether it counts toward its person's claimed and due-total, the sheet's totals and a
     * period's total: OPEN, PENDING and SETTLED do, except an OPEN or PENDING one dated within one
     * of its person's holds ({@code heldOnDate}), unless a statement binds it; and never one
     * deferred on {@code today}.
     */
    public boolean counts(boolean heldOnDate, LocalDate today) {
        if (isDeferredOn(today)) return false;
        return status == ClaimStatus.SETTLED || (isOpen() && (isBound() || !heldOnDate));
    }
    /**
     * Whether it counts toward a period's total as it was at the period's end, when its status then
     * was {@code statusThen} (null: it did not exist yet): as {@link #counts} with that status, its
     * statement binding and deferral as they are now.
     */
    public boolean countsAsOf(ClaimStatus statusThen, boolean heldOnDate, LocalDate today) {
        if (statusThen == null || isDeferredOn(today)) return false;
        boolean openThen = statusThen == ClaimStatus.OPEN || statusThen == ClaimStatus.PENDING;
        return statusThen == ClaimStatus.SETTLED || (openThen && (isBound() || !heldOnDate));
    }
    /** Whether it is open: OPEN, or PENDING a steward's approval. */
    public boolean isOpen() {
        return status == ClaimStatus.OPEN || status == ClaimStatus.PENDING;
    }
    /** Only a draft may be edited; to change an open claim, void it and add a new one. */
    public void checkEditable() throws InvalidClaimStatusException {
        if (status != ClaimStatus.DRAFT) throw new InvalidClaimStatusException(status);
    }

    /** A steward's approval of a PENDING claim: it is settled, its due fixed at {@code due}. */
    public void approve(BigDecimal due) throws InvalidClaimStatusException {
        if (status != ClaimStatus.PENDING) throw new InvalidClaimStatusException(status, ClaimStatus.SETTLED);
        status = ClaimStatus.SETTLED;
        settledDue = due;
    }
    /** A steward's rejection of a PENDING claim: it is OPEN again, bound again by its statement. */
    public void reject() throws InvalidClaimStatusException {
        if (status != ClaimStatus.PENDING) throw new InvalidClaimStatusException(status, ClaimStatus.OPEN);
        status = ClaimStatus.OPEN;
    }

    /** Move to the next status, when the current one allows it. */
    public void moveTo(ClaimStatus next) throws InvalidClaimStatusException {
        if (!status.canMoveTo(next)) throw new InvalidClaimStatusException(status, next);
        status = next;
    }
}
package net.officefloor.hq.app.claim;

import net.officefloor.plugin.variable.Val;

/** Adds a proof to the claim: not to a SETTLED or VOID claim. */
public class AddProof {
    public void apply(@Val Claim claim) throws InvalidClaimStatusException {
        claim.addProof();
    }
}
package net.officefloor.hq.app.claim;

import java.sql.Date;
import java.sql.PreparedStatement;
import java.sql.Statement;
import java.util.List;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.jdbc.core.RowMapper;
import org.springframework.jdbc.support.GeneratedKeyHolder;
import org.springframework.stereotype.Repository;

/** The claims store, kept per sheet. */
@Repository
public class ClaimRepository {

    private static final String COLUMNS = "id, sheet_id, person_id, amount, claim_date, note, status, claim_number, settled_due, opened_by, stated, stated_due, corrects, due_by, deferred_until, proofs, split_from,"
            + " (SELECT c.claim_date FROM claim c WHERE c.sheet_id = claim.sheet_id AND c.person_id = claim.person_id"
            + " AND c.claim_number = claim.corrects) AS corrected_date";

    private static final RowMapper<Claim> ROW = (rs, n) -> {
        Claim claim = new Claim(rs.getLong("id"),
            rs.getString("sheet_id"), rs.getLong("person_id"), rs.getBigDecimal("amount"),
            rs.getDate("claim_date").toLocalDate(), rs.getString("note"),
            ClaimStatus.valueOf(rs.getString("status")),
            rs.getString("claim_number"), rs.getBigDecimal("settled_due"),
            rs.getString("opened_by"));
        claim.bind(rs.getBoolean("stated"), rs.getBigDecimal("stated_due"));
        claim.setCorrects(rs.getString("corrects"));
        claim.setDueBy(rs.getDate("due_by").toLocalDate());
        java.sql.Date deferred = rs.getDate("deferred_until");
        claim.setDeferredUntil(deferred == null ? null : deferred.toLocalDate());
        claim.setProofs(rs.getInt("proofs"));
        claim.setSplitFrom(rs.getString("split_from"));
        java.sql.Date corrected = rs.getDate("corrected_date");
        claim.setCorrectedDate(corrected == null ? null : corrected.toLocalDate());
        return claim;
    };

    private final JdbcTemplate jdbc;

    public ClaimRepository(JdbcTemplate jdbc) {
        this.jdbc = jdbc;
    }

    /** The sheet's claims, newest first (a moved claim listed as made when it was moved). */
    public List<Claim> findAll(String sheetId) {
        return jdbc.query("SELECT " + COLUMNS + " FROM claim WHERE sheet_id = ? ORDER BY listed DESC, id DESC",
                ROW, sheetId);
    }

    /** The person's claims on the sheet, newest first. */
    public List<Claim> findByPerson(String sheetId, long personId) {
        return jdbc.query("SELECT " + COLUMNS + " FROM claim WHERE sheet_id = ? AND person_id = ? ORDER BY listed DESC, id DESC",
                ROW, sheetId, personId);
    }

    /** The claim with this id on the sheet, or null when there is none. */
    public Claim find(String sheetId, long id) {
        List<Claim> found = jdbc.query(
                "SELECT " + COLUMNS + " FROM claim WHERE sheet_id = ? AND id = ?", ROW, sheetId, id);
        return found.isEmpty() ? null : found.get(0);
    }

    /**
     * Mark the claim OPEN in the store when it is still DRAFT there, holding its row until the
     * request commits so two opens of the same claim cannot both go through; false when another
     * request changed it first.
     */
    public boolean markOpened(Claim claim) {
        return jdbc.update("UPDATE claim SET status = 'OPEN' WHERE id = ? AND sheet_id = ? AND status = 'DRAFT'",
                claim.getId(), claim.getSheetId()) == 1;
    }

    /**
     * The sheet's next claim number, taken in one statement so two claims opened at the same
     * moment never share a number; it is never given out again.
     */
    public int nextNumber(String sheetId) {
        return jdbc.queryForObject("SELECT last_claim_number FROM FINAL TABLE"
                + " (UPDATE sheet SET last_claim_number = last_claim_number + 1 WHERE id = ?)",
                Integer.class, sheetId);
    }

    /**
     * The next number in one period's sequence on the sheet ({@code sequence} '' for claims in no
     * period), counting from 1; taken in one statement so two claims opened at the same moment
     * never share a number, and never given out again.
     */
    public int nextNumberIn(String sheetId, String sequence) {
        jdbc.update("MERGE INTO period_number p USING (VALUES (CAST(? AS VARCHAR(200)), CAST(? AS VARCHAR(200)))) v (sheet_id, seq_name)"
                + " ON p.sheet_id = v.sheet_id AND p.seq_name = v.seq_name"
                + " WHEN NOT MATCHED THEN INSERT (sheet_id, seq_name, last_number) VALUES (v.sheet_id, v.seq_name, 0)",
                sheetId, sequence);
        return jdbc.queryForObject("SELECT last_number FROM FINAL TABLE"
                + " (UPDATE period_number SET last_number = last_number + 1 WHERE sheet_id = ? AND seq_name = ?)",
                Integer.class, sheetId, sequence);
    }

    /** The sheet's next place in its claims list, taken in one statement; never given out again. */
    private long nextListed(String sheetId) {
        return jdbc.queryForObject("SELECT last_claim_listed FROM FINAL TABLE"
                + " (UPDATE sheet SET last_claim_listed = last_claim_listed + 1 WHERE id = ?)",
                Long.class, sheetId);
    }

    /** Insert a new claim (assigning its id) or update an existing one. */
    public void save(Claim claim) {
        if (claim.getId() != null) {
            if (claim.isRelisted()) {
                jdbc.update("UPDATE claim SET person_id = ?, listed = ? WHERE id = ? AND sheet_id = ?",
                        claim.getPersonId(), nextListed(claim.getSheetId()), claim.getId(), claim.getSheetId());
            }
            jdbc.update("UPDATE claim SET amount = ?, claim_date = ?, note = ?, status = ?, claim_number = ?, settled_due = ?, opened_by = ?, stated = ?, stated_due = ?, corrects = ?, deferred_until = ?, proofs = ? WHERE id = ? AND sheet_id = ?",
                    claim.getAmount(), Date.valueOf(claim.getDate()), claim.getNote(),
                    claim.getStatus().name(), claim.getNumber(), claim.getSettledDue(), claim.getOpenedBy(),
                    claim.isStated(), claim.getStatedDue(), claim.getCorrects(),
                    claim.getDeferredUntil() == null ? null : Date.valueOf(claim.getDeferredUntil()), claim.getProofs(), claim.getId(),
                    claim.getSheetId());
            return;
        }
        long listed = nextListed(claim.getSheetId());
        GeneratedKeyHolder keys = new GeneratedKeyHolder();
        jdbc.update(con -> {
            PreparedStatement ps = con.prepareStatement(
                    "INSERT INTO claim (sheet_id, person_id, amount, claim_date, note, status, corrects, listed, due_by, split_from, claim_number, opened_by) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)",
                    Statement.RETURN_GENERATED_KEYS);
            ps.setString(1, claim.getSheetId());
            ps.setLong(2, claim.getPersonId());
            ps.setBigDecimal(3, claim.getAmount());
            ps.setDate(4, Date.valueOf(claim.getDate()));
            ps.setString(5, claim.getNote());
            ps.setString(6, claim.getStatus().name());
            ps.setString(7, claim.getCorrects());
            ps.setLong(8, listed);
            ps.setDate(9, Date.valueOf(claim.getDueBy()));
            ps.setString(10, claim.getSplitFrom());
            ps.setString(11, claim.getNumber());
            ps.setString(12, claim.getOpenedBy());
            return ps;
        }, keys);
        claim.setId(keys.getKey().longValue());
    }
}
package net.officefloor.hq.app.period;

import net.officefloor.hq.app.claim.Claim;
import net.officefloor.hq.app.sheet.Sheet;
import net.officefloor.plugin.variable.Val;

/** Refuses a change to a claim dated inside a closed period, before anything is written. */
public class CheckClaimPeriod {
    public void check(@Val Sheet sheet, @Val Claim claim, PeriodRepository periods) throws ClosedPeriodException {
        Period closed = periods.closedOn(sheet.id(), claim.getDate());
        if (closed != null) throw new ClosedPeriodException(closed.name());
    }
}
package net.officefloor.hq.app.claim;

/** A status change, or an edit, the claim's current status does not allow. */
public class InvalidClaimStatusException extends Exception {
    public InvalidClaimStatusException(ClaimStatus from, ClaimStatus to) {
        super("A " + from + " claim cannot become " + to);
    }

    /** An edit of a claim that is no longer a draft. */
    public InvalidClaimStatusException(ClaimStatus status) {
        super("A " + status + " claim cannot be edited");
    }

    /** Any other change its status does not allow. */
    public InvalidClaimStatusException(String message) {
        super(message);
    }
}
