import { useSyncExternalStore } from 'react';

// Each person's claim form, by sheet and person: the claim whose editor is open (null: the form
// adds a claim) and the values typed. Kept outside React so an open editor, which holds the
// claim's lock on the server, is still open when the sheet is loaded again.
export type Fields = { amount: string; date: string; note: string; corrects: string };
export type Editor = { editing: string | null; fields: Fields };

export const EMPTY: Fields = { amount: '', date: '', note: '', corrects: '' };
const CLOSED: Editor = { editing: null, fields: EMPTY };

const editors = new Map<string, Editor>();
const listeners = new Set<() => void>();

const keyOf = (sheetId: string, personId: string) => `${sheetId}\u0000${personId}`;

function subscribe(listener: () => void) {
  listeners.add(listener);
  return () => {
    listeners.delete(listener);
  };
}

/** The person's claim form on the sheet. */
export function useEditor(sheetId: string, personId: string): Editor {
  return useSyncExternalStore(subscribe, () => editors.get(keyOf(sheetId, personId)) ?? CLOSED);
}

/** Change the person's claim form. */
export function setEditor(sheetId: string, personId: string, next: (e: Editor) => Editor) {
  const key = keyOf(sheetId, personId);
  editors.set(key, next(editors.get(key) ?? CLOSED));
  listeners.forEach((l) => l());
}
EOF
